func parseAddress(raw string) (string, error) {
    addr := strings.TrimSpace(raw)
    if addr == "" {
        return "", fmt.Errorf("instance address is empty")
    }
    if strings.ContainsAny(addr, " \t\r\n") {
        return "", fmt.Errorf("instance address %q contains whitespace", addr)
    }
    host, port, err := net.SplitHostPort(addr)
    if err != nil {
        return "", fmt.Errorf("invalid address %q: %v", addr, err)
    }
    if host == "" {
        return "", fmt.Errorf("invalid address %q: empty host", addr)
    }
    if !isDecimalPort(port) {
        return "", fmt.Errorf("invalid address %q: port must be a decimal integer", addr)
    }
    n, _ := strconv.Atoi(port)
    if n < 1 || n > 65535 {
        return "", fmt.Errorf("invalid address %q: port %d out of range", addr, n)
    }
    if strings.HasPrefix(addr, "[") {
        ip := net.ParseIP(host)
        if ip == nil || !strings.Contains(host, ":") {
            return "", fmt.Errorf("invalid address %q: bracketed host is not IPv6", addr)
        }
    } else {
        if ip := net.ParseIP(host); ip != nil {
            // IPv4 ok; IPv6 without brackets can't reach here (SplitHostPort would fail)
        } else if !isDomainName(host) {
            return "", fmt.Errorf("invalid address %q: bad host", addr)
        }
    }
    return addr, nil
}
